  if (yueDeVal) {
    addIfIn("\u6708\u5FB7\u5408", TianGanWuHe[yueDeVal], "\u4F5C\u7528\u540C\u6708\u5FB7\uFF0C\u5409\u5E86\u7A0D\u6B21", "\u5409");
  }
  const monthIdx = DiZhiArray.indexOf(monthZhi);
  let season = "";
  if (monthIdx >= 2 && monthIdx <= 4) season = "\u6625";
